#include <bits/stdc++.h>
using namespace std;

long long recurse(long long val, long long level) {
    long long quotient = val / b[level];
    long long remainder = val % b[level];
    if (remainder == 0)
        return quotient * level;
    else
        return quotient * level + min(recurse(remainder, level - 1), level + recurse(b[level] - remainder, level - 1));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, b[20];
    for (int i = 1; i <= 17; ++i)
        b[i] = b[i - 1] * 10 + 1;
    cin >> n;
    long long count = 0, temp_n = n;
    while (temp_n != 0) {
        temp_n /= 10;
        ++count;
    }
    cout << recurse(n, count + 2) << "\n";
    return 0;
}
